import{_ as a,c as e,o as s,b0 as d}from"./chunks/framework.C5ev1SXp.js";const o="/scm-docs/assets/tftp-sequence.BuqEwAiJ.svg",u=JSON.parse('{"title":"LV025-基于TFTP的网络升级实验","description":null,"frontmatter":{"title":"LV025-基于TFTP的网络升级实验","date":"2026-10-14T21:35:41.000Z","icon":"famicons:logo-markdown","permalink":"/sdoc/advanced-chapter/ethernet/126d628e13a5261051823e07","index":true,"tags":null,"categories":null,"copyright":false,"keywords":null,"cover":null,"comments":null,"mathjax":null,"top":null,"description":null,"tdoc":{"detailDate":"2026-10-14T21:35:41.609Z","fulluuid":"051823e073bc4184a96b645919a5957c","useduuid":"051823e07"}},"headers":[],"relativePath":"sdoc/advanced-chapter/ethernet/126d628e13a5261051823e07.md","filePath":"sdoc/30-进阶篇/06-以太网/LV025-基于TFTP的网络升级实验.md","lastUpdated":1792231946000}'),n={name:"sdoc/advanced-chapter/ethernet/126d628e13a5261051823e07.md"};function r(i,t,c,p,l,h){return s(),e("div",null,[...t[0]||(t[0]=[d(`<h1 id="lv025-基于tftp的网络升级实验" tabindex="-1">LV025-基于TFTP的网络升级实验 <a class="header-anchor" href="#lv025-基于tftp的网络升级实验" aria-label="Permalink to &quot;LV025-基于TFTP的网络升级实验&quot;">​</a></h1><h2 id="一、-为什么在-tcp-之外再加一条-tftp-通道" tabindex="-1">一、 为什么在 TCP 之外再加一条 TFTP 通道 <a class="header-anchor" href="#一、-为什么在-tcp-之外再加一条-tftp-通道" aria-label="Permalink to &quot;一、 为什么在 TCP 之外再加一条 TFTP 通道&quot;">​</a></h2><p>已经有了 TCP 升级通道（<a href="/scm-docs/sdoc/advanced-chapter/ethernet/126d628e13a5205f2a80bf1e.html">LV020-网络通信实验</a> 第三节），为什么还要再做一条 TFTP？原因写在 <code>ota_tftp.h</code> 的文件头里，主要是三条：</p><p>（1）<strong>PC 侧零代码</strong>。Tftpd64 / haneWIN / SolarWinds 这类现成工具，指定一个根目录就算&quot;固件仓库&quot;，不用为升级专门写服务端；而走 TCP 就得带着那个 Python 脚本。</p><p>（2）<strong>适配紧张的内存预算</strong>。<code>lwipopts.h</code> 里 <code>MEM_SIZE</code> 只有 8 KB、<code>PBUF_POOL_SIZE</code> 只有 8 个，用 TCP 一次性拉 128 KB 固件得先把这些宏调大；TFTP 的停等协议自带流控，原样可用。</p><p>（3）<strong>不需要 DNS 与 HTTP 那一层</strong>。服务器地址由宏或命令行给出，省掉一整层协议。</p><p>一句话：TCP 通道是给&quot;有上位机脚本、要回执与确认&quot;的场景准备的；TFTP 通道是给&quot;只想把固件扔到服务器根目录、用现成工具升级&quot;准备的。两条并存，按场合选。</p><h2 id="二、-实现范围-只做够用的部分" tabindex="-1">二、 实现范围：只做够用的部分 <a class="header-anchor" href="#二、-实现范围-只做够用的部分" aria-label="Permalink to &quot;二、 实现范围：只做够用的部分&quot;">​</a></h2><h3 id="_1-明确不做的三件事" tabindex="-1">1. 明确不做的三件事 <a class="header-anchor" href="#_1-明确不做的三件事" aria-label="Permalink to &quot;1. 明确不做的三件事&quot;">​</a></h3><p>TFTP 客户端在 <code>atk-f103/Drivers/BSP/Ota/ota_tftp.c</code>，是 RFC 1350 的<strong>精简版</strong>。明确不做的三件事：</p><table tabindex="0"><thead><tr><th>不做</th><th>理由</th></tr></thead><tbody><tr><td>只做 RRQ（读），不做 WRQ（写）</td><td>升级只需要&quot;往下拉&quot;</td></tr><tr><td>不协商 <code>blksize</code> / <code>tsize</code> / <code>timeout</code> 选项</td><td>512 字节块对 128 KB 固件是 256 块，直连链路上就 1 秒量级；换来&quot;任何 TFTP 服务器都能用&quot;</td></tr><tr><td>不做断点续传</td><td>失败整份重来，128 KB 重来的代价很小</td></tr></tbody></table><p>用到的报文操作码只有四个：<code>RRQ(1)</code>、<code>DATA(3)</code>、<code>ACK(4)</code>、<code>ERROR(5)</code>。收到 <code>OACK(6)</code> 视为异常——因为本模块没协商过选项，服务器不该回它。</p><h3 id="_2-关键参数" tabindex="-1">2. 关键参数 <a class="header-anchor" href="#_2-关键参数" aria-label="Permalink to &quot;2. 关键参数&quot;">​</a></h3><table tabindex="0"><thead><tr><th>参数</th><th>取值</th></tr></thead><tbody><tr><td>服务器端口</td><td>69（标准）</td></tr><tr><td>块大小</td><td>512 字节</td></tr><tr><td>单次等待上限</td><td>1000 ms</td></tr><tr><td>最大连续重传</td><td>5 次（一旦有进展就清零）</td></tr><tr><td>固定文件名</td><td><code>app.img</code></td></tr></tbody></table><p>&quot;一旦有进展就清零&quot;这一条值得留意：<strong>重传次数统计的是&quot;连续失败&quot;，不是&quot;总失败&quot;</strong>。否则一条慢链路跑上几百个块时，累计计数很容易先到上限而误判为失败。</p><h2 id="三、-pc-侧与板侧的准备" tabindex="-1">三、 PC 侧与板侧的准备 <a class="header-anchor" href="#三、-pc-侧与板侧的准备" aria-label="Permalink to &quot;三、 PC 侧与板侧的准备&quot;">​</a></h2><h3 id="_1-pc-侧-tftp-服务器与固件帧" tabindex="-1">1. PC 侧：TFTP 服务器与固件帧 <a class="header-anchor" href="#_1-pc-侧-tftp-服务器与固件帧" aria-label="Permalink to &quot;1. PC 侧：TFTP 服务器与固件帧&quot;">​</a></h3><p><strong>这一条是最容易踩的坑</strong>：TFTP 服务器根目录下的 <code>app.img</code> 必须是 <code>tools/pack_iap.py</code> 打好的<strong>帧</strong>，不是随便一个裸 bin。帧里的魔数、长度与 CRC32 是板侧唯一的校验依据，格式细节见 <a href="/scm-docs/sdoc/advanced-chapter/ethernet/126d628e13a52a7c8f19d4b3.html">LV030-网络升级帧协议与三条通道</a> 第二节。</p><p>打包命令（<code>flash-app</code> 工程在编译后会自动跑这一步，也可以手工执行）：</p><div class="language-bash vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">python</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> tools/pack_iap.py</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -p</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> flash-app.bin</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -o</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> app.img</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -f</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>准备步骤：</p><p>（1）装一个 TFTP 服务器（Tftpd64 / haneWIN / SolarWinds 均可），把根目录指到一个空目录。</p><p>（2）把打好包的 <code>app.img</code> 放进这个根目录。</p><p>（3）把服务器所在网卡的 IP 设成板子默认要找的地址：</p><table tabindex="0"><thead><tr><th>参数</th><th>默认值</th></tr></thead><tbody><tr><td>TFTP 服务器 IP</td><td>192.168.16.100</td></tr><tr><td>板子 IP（<a href="/scm-docs/sdoc/advanced-chapter/ethernet/126d628e13a5205f2a80bf1e.html">LV020</a> 第一节）</td><td>192.168.16.30</td></tr></tbody></table><p>两者同网段即可，用不到网关。若服务器地址不方便改，可以在板子上用命令行临时指定（下一节）。</p><h3 id="_2-板侧-update-命令与注册时机" tabindex="-1">2. 板侧：update 命令与注册时机 <a class="header-anchor" href="#_2-板侧-update-命令与注册时机" aria-label="Permalink to &quot;2. 板侧：update 命令与注册时机&quot;">​</a></h3><table tabindex="0"><thead><tr><th>命令</th><th>作用</th></tr></thead><tbody><tr><td><code>update</code></td><td>从默认地址（192.168.16.100）拉取 <code>app.img</code></td></tr><tr><td><code>update 192.168.16.1</code></td><td>临时指定 TFTP 服务器地址</td></tr></tbody></table><p>命令在串口终端里输入，也可以走 TCP 通道——因为 TCP 收到的字节同样会先过一遍串口命令表。</p><p>关于注册时机：<code>update</code> 命令在 <code>ota_update_init()</code> 里注册，而它在 <code>iap_service_init()</code> 中排在 <code>usart1_rx_start()</code> <strong>之前</strong>。这不是随便排的：串口命令表只在启动阶段接受注册，注册晚了命令就不存在。同一条规矩也适用于 <code>go</code> / <code>reboot</code>，见 <a href="/scm-docs/sdoc/advanced-chapter/ethernet/126d628e13a51b6ce0b937cd.html">LV010-lwIP协议栈移植</a> 第五节。</p><h2 id="四、-一次升级的实测输出与常见失败" tabindex="-1">四、 一次升级的实测输出与常见失败 <a class="header-anchor" href="#四、-一次升级的实测输出与常见失败" aria-label="Permalink to &quot;四、 一次升级的实测输出与常见失败&quot;">​</a></h2><h3 id="_1-串口日志" tabindex="-1">1. 串口日志 <a class="header-anchor" href="#_1-串口日志" aria-label="Permalink to &quot;1. 串口日志&quot;">​</a></h3><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>OTA: fetching app.img from 192.168.16.100:69 ...</span></span>
<span class="line"><span>OTA: the file must be the IAPBIN01 frame from pack_iap.py (build output app.img)</span></span>
<span class="line"><span>OTA: progress: &#39;#&#39; = one 512-byte block, 64 per line</span></span>
<span class="line"><span>################################################################</span></span>
<span class="line"><span>################################################################</span></span>
<span class="line"><span>################################################################</span></span>
<span class="line"><span>################################################################</span></span>
<span class="line"><span>#</span></span>
<span class="line"><span>OTA: app.img transferred, 131096 bytes in 257 block(s)</span></span>
<span class="line"><span>OTA: frame handed to the IAP state machine</span></span>
<span class="line"><span>IAP: header OK, payload 131072 bytes, expected CRC32 0xXXXXXXXX, receiving...</span></span>
<span class="line"><span>IAP: frame received, CRC32 OK (0xXXXXXXXX), payload 131072 bytes</span></span>
<span class="line"><span>IAP: send &#39;go&#39; + Enter to run the APP</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br><span class="line-number">10</span><br><span class="line-number">11</span><br><span class="line-number">12</span><br><span class="line-number">13</span><br></div></div><h3 id="_2-进度条的含义" tabindex="-1">2. 进度条的含义 <a class="header-anchor" href="#_2-进度条的含义" aria-label="Permalink to &quot;2. 进度条的含义&quot;">​</a></h3><p>进度条每个 <code>#</code> 代表一个 512 字节块，一行 64 个（32 KB）。因为没协商 <code>tsize</code>，<strong>事先不知道文件多大，所以它报的是活动量而不是百分比</strong>——131096 字节是 257 块，所以是 4 整行再加末尾一个单独的 <code>#</code>。</p><p>再核对完成行的字节数：<code>131096 = 16 + 131072 + 8</code>，即&quot;帧头 16 字节 + 载荷 128 KB + 尾部 8 字节&quot;。<code>pack_iap.py</code> 组帧时<strong>不做任何填充</strong>（<code>build_packet</code> 就是&quot;头 + 载荷 + 尾&quot;直接拼接，<code>parse_packet</code> 也要求文件长度与头部声明严格相等），所以<strong>文件字节数减去 24 就是载荷字节数</strong>——这也是判断&quot;传的是帧而不是裸 bin&quot;最快的办法。</p><p>块数也可以顺手核对一遍：257 = 256 个整块 + 一个只有 24 字节的尾块（<code>16 + 8 = 24</code>），与完成行完全吻合。</p><h3 id="_3-常见失败现象对照" tabindex="-1">3. 常见失败现象对照 <a class="header-anchor" href="#_3-常见失败现象对照" aria-label="Permalink to &quot;3. 常见失败现象对照&quot;">​</a></h3><table tabindex="0"><thead><tr><th>现象</th><th>可能原因</th></tr></thead><tbody><tr><td><code>OTA: cannot start: ...</code></td><td>UDP PCB 创建/绑定失败，通常是内存池被占满</td></tr><tr><td><code>OTA: transfer failed: timeout</code></td><td>服务器没起、IP 不在同网段、防火墙拦了 69 端口</td></tr><tr><td><code>OTA: server has no &#39;app.img&#39; (tftp error 1)</code></td><td>根目录里没有这个文件名，或根目录指错了</td></tr><tr><td>进度条走完但报帧错误</td><td><strong>传的是裸 bin 而不是帧</strong>——这是最常见的一种错</td></tr><tr><td>卡在 <code>go</code> 之后起不来</td><td>检查第六节那三步关网络的代码是否都执行了；也可回看 APP 的链接地址是否与 <code>IAP_APP_BASE</code> 一致</td></tr><tr><td>想省事只发一次</td><td>TFTP 通道不提供&quot;发完自动跳转&quot;，跳转始终要显式 <code>go</code></td></tr></tbody></table><p>另外，<code>bootloader/docs/</code> 下的 <code>LV006-TFTP网络升级流程.md</code> 有这张流程的图表版，可与本文对照看。</p><h2 id="五、-下载与帧状态机怎么衔接" tabindex="-1">五、 下载与帧状态机怎么衔接 <a class="header-anchor" href="#五、-下载与帧状态机怎么衔接" aria-label="Permalink to &quot;五、 下载与帧状态机怎么衔接&quot;">​</a></h2><h3 id="_1-sink-回调的统一套路" tabindex="-1">1. sink 回调的统一套路 <a class="header-anchor" href="#_1-sink-回调的统一套路" aria-label="Permalink to &quot;1. sink 回调的统一套路&quot;">​</a></h3><p>这条通道的分工非常清楚：<strong>TFTP 模块只负责&quot;把一个文件按字节搬下来&quot;，不解释内容。</strong></p><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>PC(TFTP 服务器) --UDP--&gt; ota_tftp.c --sink 回调--&gt; iap_rx_byte()</span></span>
<span class="line"><span>                        --&gt; 主循环 iap_rx_poll() 报事件</span></span>
<span class="line"><span>                        --&gt; CRC32 校验 --&gt; 写 APP 区 --&gt; 等 &#39;go&#39; 跳转</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br></div></div><img src="`+o+`" alt="TFTP 停等传输与 IAP 帧状态机的衔接"><p>数据出口用的是&quot;注册 sink 回调&quot;这套路，和串口通道的 <code>usart1_set_rx_sink()</code> 完全一致：</p><table tabindex="0"><thead><tr><th>阶段</th><th>动作</th></tr></thead><tbody><tr><td>传输期间</td><td><code>usart1_set_rx_sink(0)</code> 摘掉串口消费器，只让 TFTP 喂状态机</td></tr><tr><td>传输成功</td><td>sink 保留给帧状态机，<code>ota_update_task()</code> 不再抢这一步</td></tr><tr><td>传输失败</td><td><code>iap_rx_init()</code> 丢弃半截帧，回到扫描态</td></tr><tr><td>失败但帧已报错</td><td>提前 <code>ota_tftp_abort()</code>，不白等整份下载</td></tr></tbody></table><p>这里有个设计取舍值得记：<strong>帧校验与写 Flash 全部复用 <code>iap.c</code>，本模块一行不重复实现</strong>。所以三条通道（串口 / TCP / TFTP）的帧语义永远一致，不会出现&quot;TFTP 升级的校验规则和串口不一样&quot;这种事。</p><h3 id="_2-两个必须守住的协议细节" tabindex="-1">2. 两个必须守住的协议细节 <a class="header-anchor" href="#_2-两个必须守住的协议细节" aria-label="Permalink to &quot;2. 两个必须守住的协议细节&quot;">​</a></h3><p><code>ota_tftp.c</code> 的文件头专门写明了两个坑，都属于&quot;不这么做就一定出错&quot;的类型：</p><p>（1）<strong>服务器收到 RRQ 后会换一个端口（TID）发数据</strong>。所以客户端只能先 <code>udp_sendto()</code> 到 69 端口，收到第一个应答后再锁定对端；一上来就 <code>udp_connect()</code> 到 69，后续所有 DATA 都收不到。</p><p>（2）<strong>重复块只补 ACK，绝不重复交给上层</strong>。ACK 丢了服务器会重发同一块，如果把这块数据再喂一次状态机，上层立刻错位——同一段固件被写两遍。</p><h2 id="六、-互斥、跳转与完整流程" tabindex="-1">六、 互斥、跳转与完整流程 <a class="header-anchor" href="#六、-互斥、跳转与完整流程" aria-label="Permalink to &quot;六、 互斥、跳转与完整流程&quot;">​</a></h2><h3 id="_1-与-tcp-通道的互斥" tabindex="-1">1. 与 TCP 通道的互斥 <a class="header-anchor" href="#_1-与-tcp-通道的互斥" aria-label="Permalink to &quot;1. 与 TCP 通道的互斥&quot;">​</a></h3><p>三条通道最终都喂进<strong>同一个</strong>帧状态机，所以同一时刻只能有一条在工作。互斥在两个方向上各做了一次检查：</p><table tabindex="0"><thead><tr><th>场景</th><th>检查点</th><th>行为</th></tr></thead><tbody><tr><td>TFTP 传输中，来了 TCP 客户端</td><td><code>iap_tcp.c</code> 的 accept 回调</td><td>直接 <code>tcp_abort</code> 关连接，让 PC 侧立刻看到失败</td></tr><tr><td>TCP 会话中，输入 <code>update</code></td><td><code>ota_update.c</code> 的 <code>cmd_update()</code></td><td>打印 <code>OTA: refused, an IAP-TCP session is active</code> 并返回</td></tr></tbody></table><p>这样设计是为了<strong>让失败尽早暴露</strong>：与其让两路字节混进同一个状态机、收下半帧垃圾才报错，不如在入口处就拒掉。</p><h3 id="_2-跳转-app-前必须把网络关干净" tabindex="-1">2. 跳转 APP 前必须把网络关干净 <a class="header-anchor" href="#_2-跳转-app-前必须把网络关干净" aria-label="Permalink to &quot;2. 跳转 APP 前必须把网络关干净&quot;">​</a></h3><p>这是整个网络升级里最隐蔽的一个坑，提交 <code>fix(iap): 跳转 APP 前关闭网络通道, 修复 APP 起步后卡死</code> 就是在修它。</p><p>问题的成因：</p><ul><li><code>SCB-&gt;VTOR</code> 在跳转时会指向 APP 的向量表，但 <strong>NVIC 的 <code>EXTI9_5</code> 使能位不会被 APP 复位</strong>；</li><li>如果跳转前还留着一个使能的 DM9000 中断，APP 起步后收到的第一个网络包就会落进 APP 自己的 <code>Default_Handler</code>（<code>while(1)</code>）里卡死。</li></ul><p>所以 <code>iap_tcp_shutdown()</code> 在 <code>iap_load_app()</code> <strong>之前</strong>被调用，做五件事：</p><div class="language-c vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">c</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">DM9000_WriteReg</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(DM9000_IMR, IMR_PAR);</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">                    /* 1. 关网卡中断源 */</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">DM9000_WriteReg</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(DM9000_RCR, RCR_DIS_LONG </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">|</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> RCR_DIS_CRC);</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">  /*    停接收(RXEN=0) */</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">HAL_NVIC_DisableIRQ</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(EXTI9_5_IRQn);</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">                       /* 2. 关 EXTI 中断线 */</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">HAL_NVIC_ClearPendingIRQ</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(EXTI9_5_IRQn);</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">__HAL_GPIO_EXTI_CLEAR_IT</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(DM9000_INT_Pin);</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">                /*    清 GPIO 侧挂起 */</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">session_close</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">();</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">                                         /* 3. 关 TCP 会话 */</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br></div></div><p>必须&quot;关三处&quot;而不是只关一处：<strong>网卡侧的中断源、NVIC 侧的中断使能、TCP 会话</strong>。少任何一处，跳转后都留着一条能触发中断的通路。同样的处理在 <code>reboot</code> 命令里也有一份：软复位不会复位<strong>外置</strong>的 DM9000，不关的话重启初期 GPIO 已经使能 EXTI、而 FSMC 还没初始化，残留中断会打在那个窗口里。</p><h3 id="_3-完整升级流程" tabindex="-1">3. 完整升级流程 <a class="header-anchor" href="#_3-完整升级流程" aria-label="Permalink to &quot;3. 完整升级流程&quot;">​</a></h3><table tabindex="0"><thead><tr><th>步骤</th><th>谁做</th><th>动作</th></tr></thead><tbody><tr><td>1</td><td>PC</td><td>编译 APP，<code>pack_iap.py</code> 打包出 <code>app.img</code></td></tr><tr><td>2</td><td>PC</td><td>把 <code>app.img</code> 放进 TFTP 服务器根目录，确认服务器 IP</td></tr><tr><td>3</td><td>板子</td><td>串口终端输入 <code>update</code>（或 <code>update &lt;服务器IP&gt;</code>）</td></tr><tr><td>4</td><td>双方</td><td>RRQ → DATA/ACK 停等传输，板子打进度条</td></tr><tr><td>5</td><td>板子</td><td>帧收齐 → CRC32 校验 → 写 APP 区 → 回读比对</td></tr><tr><td>6</td><td>板子</td><td>提示 <code>send &#39;go&#39; + Enter to run the APP</code></td></tr><tr><td>7</td><td>板子</td><td>输入 <code>go</code>：先 <code>iap_tcp_shutdown()</code> 关网络，再跳转 APP</td></tr></tbody></table><p>用 TFTP 通道时<strong>不需要</strong> TCP 会话，所以第 3 步之后直接等进度条走完即可。</p><h2 id="七、-小结与参考资料" tabindex="-1">七、 小结与参考资料 <a class="header-anchor" href="#七、-小结与参考资料" aria-label="Permalink to &quot;七、 小结与参考资料&quot;">​</a></h2><h3 id="_1-本篇小结" tabindex="-1">1. 本篇小结 <a class="header-anchor" href="#_1-本篇小结" aria-label="Permalink to &quot;1. 本篇小结&quot;">​</a></h3><ul><li>TFTP 通道的价值是&quot;PC 侧零代码 + 自带流控&quot;，代价是只能手动触发、发完要显式 <code>go</code>。</li><li>实现上只做 RRQ，不协商选项、不做断点续传；服务器端口 69、块大小 512、单次等待 1s、连续重传上限 5 次。</li><li>服务器根目录里必须放<strong>打好包的帧</strong>（<code>app.img</code>），裸 bin 是最常见的失败原因。</li><li>板侧入口是 <code>update</code> 命令，它必须在 <code>usart1_rx_start()</code> 之前注册。</li><li>传输通过 sink 回调把字节喂给统一的帧状态机；必须处理&quot;服务器换 TID 端口&quot;与&quot;重复块只补 ACK&quot;两个细节。</li><li>三条通道共用同一个状态机，因此在入口处互相拒绝；跳转 APP 前必须同时关掉网卡中断源、NVIC 中断使能与 TCP 会话。</li></ul><h3 id="_2-参考资料" tabindex="-1">2. 参考资料 <a class="header-anchor" href="#_2-参考资料" aria-label="Permalink to &quot;2. 参考资料&quot;">​</a></h3><ul><li>手册：<a href="https://gitee.com/docs-site/scm-reference-guide/raw/main/30-STM32%E8%B5%84%E6%96%99/10-lwIP/STM32F1%20LWIP%E5%BC%80%E5%8F%91%E6%89%8B%E5%86%8C%28DM9000%E7%89%88%29_V1.1.pdf" target="_blank" rel="noreferrer"><code>30-STM32资料/10-lwIP/STM32F1 LWIP开发手册(DM9000版)_V1.1.pdf</code></a> 第三章「RAW 编程接口 UDP 实验」（TFTP 建立在 UDP RAW API 之上）</li><li>源码：<a href="https://cnb.cool/smk.k/Microcontroller/bootloader/-/blob/main/atk-f103/Drivers/BSP/Ota/ota_tftp.c" target="_blank" rel="noreferrer"><code>ota_tftp.c</code></a>、<a href="https://cnb.cool/smk.k/Microcontroller/bootloader/-/blob/main/atk-f103/Drivers/BSP/Ota/ota_tftp.h" target="_blank" rel="noreferrer"><code>ota_tftp.h</code></a>、<a href="https://cnb.cool/smk.k/Microcontroller/bootloader/-/blob/main/atk-f103/Drivers/BSP/Ota/ota_update.c" target="_blank" rel="noreferrer"><code>ota_update.c</code></a>、<a href="https://cnb.cool/smk.k/Microcontroller/bootloader/-/blob/main/atk-f103/Components/lwip-2.1.3/port/iap_tcp.c" target="_blank" rel="noreferrer"><code>iap_tcp.c</code></a></li><li>上位机与打包：<a href="https://cnb.cool/smk.k/Microcontroller/bootloader/-/blob/main/tools/pack_iap.py" target="_blank" rel="noreferrer"><code>tools/pack_iap.py</code></a>、<a href="https://cnb.cool/smk.k/Microcontroller/bootloader/-/blob/main/tools/send_iap_tcp.py" target="_blank" rel="noreferrer"><code>tools/send_iap_tcp.py</code></a></li><li>相关提交：<a href="https://cnb.cool/smk.k/Microcontroller/bootloader/-/commit/005c507512b0799131862dbeb52c436628ca4aa5" target="_blank" rel="noreferrer">新增基于 TFTP 的手动网络升级通道</a>、<a href="https://cnb.cool/smk.k/Microcontroller/bootloader/-/commit/289455ea0db06932e8acf6c1a137f30cda895714" target="_blank" rel="noreferrer">新增 LV006 TFTP 网络升级流程文档与三张配图</a>、<a href="https://cnb.cool/smk.k/Microcontroller/bootloader/-/commit/cca3fea570b1cffa0975f37db2fa47ce9cd8cc89" target="_blank" rel="noreferrer">跳转 APP 前关闭网络通道</a></li></ul><hr><p><em>本文档由 markdowncli 技能辅助生成</em></p>`,74)])])}const k=a(n,[["render",r]]);export{u as __pageData,k as default};
